from collections import deque


def shortest_path(graph: dict, start, goal) -> list | None:
    prev = {start: None}
    q = deque([start])
    while q:
        node = q.popleft()
        if node == goal:
            path = []
            while node is not None:
                path.append(node)
                node = prev[node]
            return path[::-1]
        for nxt in graph.get(node, []):
            if nxt not in prev:
                prev[nxt] = node
                q.append(nxt)
    return None
```

Breadth-first search reaches each node by a fewest-edges route first, and the prev map doubles as the visited set. It assumes no node is literally None.

